const addEventListenerToAddToCartBtns=()=>{const addToCartBtn=document.querySelector(".add-to-cart-btn");addToCartBtn.addEventListener("click",async()=>{const btnContainer=addToCartBtn.parentElement;try{const res=await axios.post(`/user_cart/${addToCartBtn.id}/add`);const link=document.createElement("a");link.href="/user_cart";link.classList.add("btn","btn-secondary","go-to-cart-btn");link.innerText="Go To Cart";btnContainer.appendChild(link);btnContainer.removeChild(addToCartBtn);setCartItemCount();showToast(res.data)}catch(err){showToast({error:"Error Adding Product to Cart!"})}})};const addEventListenerToAddToBuyNowBtns=()=>{const buyNowBtn=document.querySelector(".buy-now-btn");buyNowBtn.addEventListener("click",async()=>{try{const bookData={bookIdsAndQty:[{bookId:buyNowBtn.id,cart_qty:1}]};const res=await axios.post("/order_placing",bookData);showToast(res.data);if(res.data.success){window.location="/order_placing"}}catch(err){showToast({error:"Cannot Contact Server!"})}})};addEventListenerToAddToBuyNowBtns();addEventListenerToAddToCartBtns();